export default async function next({ events, previous, acknowledge, resolution }, ctx) {
  const state = previous ?? { index: 0 };
  while (state.index < events.length) {
    const e = events[state.index++];
    if (e.eventType !== "file_created" || e.mimeType !== "image/jpeg") continue;
    const key = "drive-xmp:" + e.fileId;
    let record = await ctx.state.get(key);
    if (record?.status === "pending") {
      if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
        throw Error("Inspect pending image update " + key);
      if (resolution === "confirmed") {
        await ctx.state.set(key, { status: "done" });
        continue;
      }
      await ctx.state.set(key, null);
      record = null;
    }
    if (record?.status === "done") continue;
    if (record) throw Error("Invalid image state");
    return { state, more: true, fileId: e.fileId, key };
  }
  return { state, more: false, fileId: "unused", key: "" };
}

