import { Buffer } from "node:buffer";
export default async function prepare({ file }, ctx) {
  if (file?.mimeType !== "image/jpeg" || !file.transitUrl?.startsWith("https://"))
    throw Error("Expected JPEG transit");
  const r = await ctx.fetch(file.transitUrl);
  if (!r.ok) throw Error("JPEG download failed");
  const b = Buffer.from(await r.arrayBuffer());
  if (
    b.length < 4 ||
    b[0] !== 255 ||
    b[1] !== 216 ||
    (typeof file.sizeBytes === "number" && b.length !== file.sizeBytes)
  )
    throw Error("Invalid or incomplete JPEG");
  const data = b.toString("base64");
  return {
    data,
    body: {
      contents: [
        {
          parts: [
            { inline_data: { mime_type: "image/jpeg", data } },
            {
              text: "List descriptive keywords for this image. Return a JSON array of short strings only.",
            },
          ],
        },
      ],
      generationConfig: { response_mime_type: "application/json" },
    },
  };
}

