export default async function f({ key, id, expected }, ctx) {
  if (id !== expected) throw Error("Inspect Drive update");
  const old = await ctx.state.get(key);
  if (old?.status !== "pending") throw Error("Unexpected image state");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}
